import{z as B,x as d,o as i,c as A,q as s,j as o,D as e,d as t,s as n,S as r,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"二阶占优与均值保持展开","description":"","frontmatter":{"title":"二阶占优与均值保持展开","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/sosd-mps.md","filePath":"econ/sosd-mps.md","lastUpdated":1791063341000}'),p={name:"econ/sosd-mps.md"};function S(D,a,m,h,u,c){const l=d("Mermaid");return i(),A("div",null,[a[2]||(a[2]=s('<h1 id="二阶占优与均值保持展开" tabindex="-1">二阶占优与均值保持展开 <a class="header-anchor" href="#二阶占优与均值保持展开" aria-label="Permalink to &quot;二阶占优与均值保持展开&quot;">​</a></h1><div class="epigraph"><p>均值相同的两份分布，二阶占优与「加上均值为零的噪声」是同一句话——方差更大既非定义，也非充分。</p><footer>—— 据 Rothschild and Stiglitz, Increasing Risk: I. A Definition, Journal of Economic Theory, 1970 整理</footer></div><p><a href="/econ/stochastic-dominance">上一课</a>给出了 FSD 与 SSD 的积分条件，并把「更有风险」点名到均值保留展开。本课不重写一阶占优，也不把生存函数再推一遍。缺口是把 SOSD 与 Rothschild–Stiglitz 展形收成一组等价定义：何时「一切凹 \\(u\\) 都同意更差」就是「同一均值加噪声」，以免后课把方差排序或上一课的均值方差刀刃误当成占优。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SSD 允许均值不同：均值更低且更散，递增凹的人可以一致讨厌。Rothschild–Stiglitz 问的是更窄的一句：均值已经对齐，风险是否增加。缺口是三条等价，而不是再画一条 CDF：</p><ol><li>\\(Y=X+\\tilde\\varepsilon\\)，其中 \\(\\mathbb{E}(\\tilde\\varepsilon\\mid X)=0\\) 几乎处处（均值保持展开，MPS）。</li><li>对一切凹函数 \\(u\\)，\\(\\mathbb{E}u(X)\\ge\\mathbb{E}u(Y)\\)（不必递增）。</li><li>\\(\\int_{-\\infty}^x F_X\\le\\int_{-\\infty}^x F_Y\\) 对一切 \\(x\\)，且两端均值相等。</li></ol><p>有了等价，后课写「风险增加」必须能指出噪声或积分条件，不能只报 \\(\\sigma_Y\\gt \\sigma_X\\)。上一课已警告方差不是 SOSD；本课把这句话收成定义。</p><p><span class="marginnote">术语翻译：均值保持展开（MPS）就是把分布「拉胖」但不挪中心——像把一堆沙从中间铲到两边：沙的总重量（均值）不变，只是铺得更开。Rothschild–Stiglitz 说，风险增加就指这件事，不多也不少。</span></p><h3 id="等均值的-sosd-才是展形" tabindex="-1">等均值的 SOSD 才是展形 <a class="header-anchor" href="#等均值的-sosd-才是展形" aria-label="Permalink to &quot;等均值的 SOSD 才是展形&quot;">​</a></h3><p>若均值不等，SOSD 更弱：它可以来自「左移」而不是展形。FSD 蕴含 SOSD，但 FSD 会改均值。故「二阶占优」四个字不够钉风险增加；必须加均值相同，或直接说 MPS。Hadar–Russell 的积分条件覆盖不等均值；Rothschild–Stiglitz 1970 钉的是等均值那一层。</p><p><span class="marginnote">单次交叉：两条 CDF 交叉一次且均值相等，往往给出 MPS，但不是定义。多峰、离散支撑上要回到积分或噪声表示。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象仍是一维财富的客观分布，与主干 \\(\\mathbb{E}u\\) 一致。构造 MPS：从 \\(X\\) 的某区间取走中间质量，对称地堆到两端，保持均值，即「展形」。反过来，任何条件均值零的噪声都是一次展形；复合若干次仍是 MPS。</p><p>比较两个已给的分布：先查均值；再查积分条件（3）。不必估 \\(u\\)，也不必估 \\(r_A\\)。这与<a href="/econ/revealed-preference">显示偏好</a>用成对观测打公理同类：直接打在分布上。</p>',14)),(i(),o(r,null,{default:e(()=>[n(l,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20SSD%5B%22SOSD%EF%BC%9A%E4%B8%80%E5%88%87%E9%80%92%E5%A2%9E%E5%87%B9%20u%22%5D%20--%3E%20EQ%5B%22%E5%8A%A0%E4%B8%8A%E5%9D%87%E5%80%BC%E7%9B%B8%E7%AD%89%22%5D%0A%20%20EQ%20--%3E%20MPS%5B%22MPS%EF%BC%9AY%20%3D%20X%20%2B%20%E9%9B%B6%E6%9D%A1%E4%BB%B6%E5%9D%87%E5%80%BC%E5%99%AA%E5%A3%B0%22%5D%0A%20%20MPS%20--%3E%20INT%5B%22%E7%A7%AF%E5%88%86%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20MPS%20--%3E%20CONC%5B%22%E4%B8%80%E5%88%87%E5%87%B9%20u%EF%BC%8C%E4%B8%8D%E5%BF%85%E9%80%92%E5%A2%9E%22%5D%0A%20%20INT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%BB%99%E7%8A%B6%E6%80%81%E8%B5%B7%E5%90%8D%E5%AD%97%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"本课仍比较无名分布。哪一个状态穷、有没有 Arrow 证券，下一课才引入。也不把展形写成限价簿上的波动率上升。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"噪声表示的机制是 Jensen：凹函数对条件均值零的扰动掉期望，故一切风险厌恶者（凹 \\(u\\)）都讨厌 MPS。积分条件的机制是把二阶差分累加：CDF 的面积差记录「左边堆了多少未能被右边补偿的质量」。方差只看见二阶矩，看不见质量如何搬；把质量搬到更远的两端可以保持方差却改变更高阶，也可以增大方差却被某条凹 \\(u\\) 喜欢——故方差不是等价项。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"数字实例：财富 100，效用 \\(u(x)=\\sqrt{x}\\)。确定的 100 给效用 10；改成各半概率得 64 或 136（均值仍是 100），期望效用约 \\((8+11.7)/2=9.83 \\lt 10\\)。均值没变、只是更散，凹效用立刻变差——这就是 Jensen 在展形上的算术。")],-1)),(i(),o(r,null,{default:e(()=>[n(l,{id:"mermaid-67",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%8E%9F%E5%88%86%E5%B8%83%20X%EF%BC%9A%E8%B4%A8%E9%87%8F%E9%9B%86%E4%B8%AD%E5%9C%A8%E4%B8%AD%E9%97%B4%22%5D%20--%3E%20TAKE%5B%22%E4%BB%8E%E4%B8%AD%E9%97%B4%E6%90%AC%E8%B5%B0%E4%B8%80%E5%B0%8F%E5%9D%97%E6%A6%82%E7%8E%87%E8%B4%A8%E9%87%8F%22%5D%0A%20%20TAKE%20--%3E%20L%5B%22%E4%B8%80%E5%8D%8A%E6%90%AC%E5%88%B0%E5%B7%A6%E7%AB%AF%E6%9B%B4%E8%BF%9C%E5%A4%84%22%5D%0A%20%20TAKE%20--%3E%20R%5B%22%E4%B8%80%E5%8D%8A%E6%90%AC%E5%88%B0%E5%8F%B3%E7%AB%AF%E6%9B%B4%E8%BF%9C%E5%A4%84%22%5D%0A%20%20L%20--%3E%20KEEP%5B%22%E5%AF%B9%E7%A7%B0%E6%90%AC%E8%BF%90%EF%BC%8C%E5%9D%87%E5%80%BC%E4%B8%8D%E5%8F%98%22%5D%0A%20%20R%20--%3E%20KEEP%0A%20%20KEEP%20--%3E%20Y%5B%22%E5%BE%97%E5%88%B0%20Y%EF%BC%9A%E6%9B%B4%E5%B1%95%E5%BD%A2%EF%BC%8C%E5%9D%87%E5%80%BC%E7%9B%B8%E5%90%8C%22%5D%0A%20%20Y%20--%3E%20JEN%5B%22%E4%B8%80%E5%88%87%E5%87%B9%20u%20%E7%9A%84%E6%9C%9F%E6%9C%9B%E6%95%88%E7%94%A8%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p>与<a href="/econ/mean-variance-eu">均值方差</a>的分工：MV 在二次或正态刀刃上用 \\((\\mu,\\sigma)\\)；本课在一般分布上用整条 \\(F\\)。正态且均值相同，\\(\\sigma\\) 更大确是 MPS，这是刀刃上的重逢，不是一般定义。</p><p><span class="marginnote">常见误区：「更有风险 = 方差更大」。方差只看二阶矩，看不见质量搬到了哪里。判断风险增加要看整条分布的积分条件或噪声表示，只报一个 \\(\\sigma\\) 在一般分布上两头都会错。</span></p><p><span class="marginnote">Rothschild–Stiglitz 的「increasing risk」不要译成「方差增加」。原文三条等价里没有方差。后续他们讨论风险增加如何改变储蓄、组合，那是应用，本课只钉定义。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>占优是偏序：许多等均值的分布对不可比，必须回到特定 \\(u\\) 或 \\(r_A\\)。三阶占优、下偏距对应谨慎，主干用不到。多维结果要把噪声写成随机向量，积分条件改成多维；本课只钉一维。</p><p>独立性失败时，\\(\\mathbb{E}u\\) 表示不成立，SOSD 的效用刻画一起塌；积分条件仍可作为分布的几何性质，但不再等于「一切风险厌恶者」。主干仍在 vNM 内部使用本课。模糊没有 \\(F\\) 可积。</p><p>后课默认：「更有风险」指 Rothschild–Stiglitz 的 MPS；等均值的 SOSD 与之等价，方差排序不算数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>等均值时，SOSD、一切凹 \\(u\\) 同意、MPS 三条等价。</li><li>不等均值的 SOSD 可以只是左移，不是展形。</li><li>方差更大既非必要也非充分；正态刀刃上才重逢。</li><li>本课仍比较无名分布；下一课给状态起名字。</li><li>出处：Rothschild and Stiglitz, <em>Journal of Economic Theory</em>, 1970；Hadar and Russell, <em>AER</em>, 1969。</li></ul>',9))])}const f=B(p,[["render",S]]);export{F as __pageData,f as default};
